#!/usr/bin/env python3
"""Patch the Android runner generated by `flutter create --platforms=android`.

The repository does not commit the platform runners yet (see docs/platform-setup.md).
CI generates android/ and this script applies the SARCADE-specific settings:

- INTERNET permission (the Flutter template only declares it for debug builds)
- foreground location permissions used by geolocator
- cleartext HTTP/WS, needed while the V0.1 server is reached as http://IP:8000 on a LAN
- application label "SARCADE"
- hardware features declared optional (touchscreen, GPS, location), so the
  Play Store also offers the app on Chromebooks without touch screen or GPS:
  a location permission otherwise implies a required GPS feature
- foreground service of location for the Beacon (positions screen off)
- dictation: RECORD_AUDIO and the speech recognition service in <queries>
- notifications (POST_NOTIFICATIONS, Android 13+) and core library
  desugaring in the Gradle build, required by flutter_local_notifications
- notification actions (Accept, Refuse, Read, Open) and reminders of the
  immediate messages: receivers of flutter_local_notifications, boot
  receiver, vibration, access to the Do Not Disturb policy (asked only with
  the consent of the operator)

- release signing with the fixed SARCADE key when the CI provides it
  (SARCADE_KEYSTORE and passwords in the environment, from GitHub secrets):
  test APKs then update in place instead of requiring an uninstall. Without
  it, the template's debug signing stays (random key on each CI machine).

The script is idempotent and fails loudly if the template changed shape.
"""
import re
import sys
from pathlib import Path

import os

MANIFEST = Path("android/app/src/main/AndroidManifest.xml")
SIGNING = """    signingConfigs {
        create("sarcade") {
            storeFile = file(System.getenv("SARCADE_KEYSTORE")!!)
            storePassword = System.getenv("SARCADE_KEYSTORE_PASSWORD")
            keyAlias = System.getenv("SARCADE_KEY_ALIAS")
            keyPassword = System.getenv("SARCADE_KEYSTORE_PASSWORD")
        }
    }
"""


def patch_signing() -> int:
    """Release builds signed with the fixed SARCADE key (CI only)."""
    if not os.environ.get("SARCADE_KEYSTORE"):
        print("signing: no SARCADE_KEYSTORE, debug signing kept")
        return 0
    if not GRADLE_KTS.exists():
        print(f"error: {GRADLE_KTS} not found (template changed?)", file=sys.stderr)
        return 1
    gradle = GRADLE_KTS.read_text(encoding="utf-8")
    if 'create("sarcade")' not in gradle:
        gradle, n = re.subn(r"(\n\s*buildTypes\s*\{)", "\n" + SIGNING.rstrip("\n") + r"\1", gradle, count=1)
        if n != 1:
            print("error: buildTypes block not found in build.gradle.kts", file=sys.stderr)
            return 1
    gradle, n = re.subn(r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
                        'signingConfig = signingConfigs.getByName("sarcade")', gradle)
    if n == 0 and 'getByName("sarcade")' not in gradle:
        print("error: release signingConfig not found in build.gradle.kts", file=sys.stderr)
        return 1
    GRADLE_KTS.write_text(gradle, encoding="utf-8")
    print(f"signing: release signed with the SARCADE key ({GRADLE_KTS})")
    return 0
OPTIONAL_FEATURES = [
    "android.hardware.touchscreen",
    "android.hardware.location",
    "android.hardware.location.gps",
    "android.hardware.location.network",
]
PERMISSIONS = [
    "android.permission.INTERNET",
    "android.permission.ACCESS_NETWORK_STATE",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.ACCESS_COARSE_LOCATION",
    "android.permission.POST_NOTIFICATIONS",
    # Dictation (speech_to_text): microphone, speech service of the device.
    "android.permission.RECORD_AUDIO",
    # Beacon: positions keep going screen off, from a location foreground service.
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_LOCATION",
    "android.permission.WAKE_LOCK",
    # Notification actions and reminders of the immediate messages.
    "android.permission.VIBRATE",
    "android.permission.RECEIVE_BOOT_COMPLETED",
    "android.permission.ACCESS_NOTIFICATION_POLICY",
]
RECEIVERS = """
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ActionBroadcastReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
"""
GRADLE_KTS = Path("android/app/build.gradle.kts")
GRADLE = Path("android/app/build.gradle")
DESUGAR = "com.android.tools:desugar_jdk_libs:2.1.5"


def patch_gradle() -> bool:
    """Core library desugaring (Java 8+ APIs on older Android versions)."""
    if GRADLE_KTS.exists():
        path, kts = GRADLE_KTS, True
    elif GRADLE.exists():
        path, kts = GRADLE, False
    else:
        print("error: android/app/build.gradle(.kts) not found", file=sys.stderr)
        return False
    text = path.read_text(encoding="utf-8")
    flag = "isCoreLibraryDesugaringEnabled = true" if kts else "coreLibraryDesugaringEnabled true"
    if flag not in text:
        text, n = re.subn(r"(compileOptions\s*\{)", r"\1\n        " + flag, text, count=1)
        if n != 1:
            print("error: compileOptions block not found", file=sys.stderr)
            return False
    dep = f'coreLibraryDesugaring("{DESUGAR}")' if kts else f"coreLibraryDesugaring '{DESUGAR}'"
    if "coreLibraryDesugaring(" not in text and "coreLibraryDesugaring '" not in text:
        if re.search(r"^dependencies\s*\{", text, flags=re.M):
            text = re.sub(r"^dependencies\s*\{", "dependencies {\n    " + dep, text, count=1, flags=re.M)
        else:
            text += "\ndependencies {\n    " + dep + "\n}\n"
    path.write_text(text, encoding="utf-8")
    print(f"patched {path}")
    return True


def main() -> int:
    if not MANIFEST.exists():
        print(f"error: {MANIFEST} not found, run flutter create first", file=sys.stderr)
        return 1
    xml = MANIFEST.read_text(encoding="utf-8")

    missing = [p for p in PERMISSIONS if f'android:name="{p}"' not in xml]
    features = [f for f in OPTIONAL_FEATURES if f'android:name="{f}"' not in xml]
    if missing or features:
        block = "".join(f'    <uses-permission android:name="{p}"/>\n' for p in missing)
        block += "".join(f'    <uses-feature android:name="{f}" android:required="false"/>\n' for f in features)
        xml, n = re.subn(r"(\n\s*<application\b)", "\n" + block.rstrip("\n") + r"\1", xml, count=1)
        if n != 1:
            print("error: <application> element not found", file=sys.stderr)
            return 1

    def patch_application(match: re.Match) -> str:
        tag = match.group(0)
        tag = re.sub(r'android:label="[^"]*"', 'android:label="SARCADE"', tag)
        if "android:usesCleartextTraffic" not in tag:
            tag = tag.replace("<application", '<application\n        android:usesCleartextTraffic="true"', 1)
        return tag

    # Android 11+: the speech recognition service must be declared visible.
    speech = '<intent><action android:name="android.speech.RecognitionService"/></intent>'
    if "android.speech.RecognitionService" not in xml:
        if "<queries>" in xml:
            xml = xml.replace("<queries>", "<queries>\n        " + speech, 1)
        else:
            xml = xml.replace("</manifest>", "    <queries>\n        " + speech + "\n    </queries>\n</manifest>", 1)
    xml, n = re.subn(r"<application\b[^>]*>", patch_application, xml, count=1)
    if n != 1:
        print("error: <application> element not found", file=sys.stderr)
        return 1

    if "ActionBroadcastReceiver" not in xml:
        xml, n = re.subn(r"(\n\s*</application>)", RECEIVERS.rstrip("\n") + r"\1", xml, count=1)
        if n != 1:
            print("error: </application> not found", file=sys.stderr)
            return 1

    MANIFEST.write_text(xml, encoding="utf-8")
    print(f"patched {MANIFEST}")
    if not patch_gradle():
        return 1
    return patch_signing()


if __name__ == "__main__":
    sys.exit(main())
